import React, { useEffect, useState } from 'react';

const Ahorro = () => {
    const [salario, setSalario] = useState(0); // Estado para el salario
    const [gastos, setGastos] = useState([]); // Estado para los gastos
    const [loading, setLoading] = useState(true); // Estado de carga

    useEffect(() => {
        // Simulando la carga de datos (esto podría ser una llamada a una API)
        const fetchData = async () => {
            setLoading(true);
            try {
                // Aquí deberías cargar los datos desde tu base de datos
                const data = {
                    salario: 3000, // Simulando un salario
                    gastosMensuales: [
                        { id: 1, nombre: 'Alquiler', cantidad: 1000 },
                        { id: 2, nombre: 'Comida', cantidad: 300 },
                        { id: 3, nombre: 'Transporte', cantidad: 150 },
                    ],
                };

                setSalario(data.salario);
                setGastos(data.gastosMensuales);
            } catch (error) {
                console.error('Error al cargar los datos:', error);
            } finally {
                setLoading(false);
            }
        };

        fetchData();
    }, []);

    if (loading) {
        return <div>Cargando datos de ahorro...</div>; // Mensaje de carga
    }

    return (
        <>
            <div className="ahorro-container">
                <h1 className="ahorro-title">Ahorro</h1>
                <div className="ahorro-content">
                    <h2>Salario Mensual: ${salario}</h2>
                    <h3>Gastos Mensuales</h3>
                    <table>
                        <thead>
                            <tr>
                                <th>ID</th>
                                <th>Nombre</th>
                                <th>Cantidad</th>
                            </tr>
                        </thead>
                        <tbody>
                            {gastos.map((gasto) => (
                                <tr key={gasto.id}>
                                    <td>{gasto.id}</td>
                                    <td>{gasto.nombre}</td>
                                    <td>${gasto.cantidad}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </>
    );
};

export default Ahorro;
